-- A claim may carry an external reference (null: none), unique on its sheet without regard to case: ref_key is the
-- reference in lower case, which the unique index holds to once per sheet (nulls repeat freely). Kept in the claim's
-- history too (see V39). The journal trigger is made again around the change, as in V41.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN ref VARCHAR(4000);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN ref VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN ref_key VARCHAR(4000);
CREATE UNIQUE INDEX claim_ref_unique ON claim (sheet_id, ref_key);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- A claim may carry tags: kept trimmed, lower-cased, without repeats and sorted, comma separated (null: none). Kept in
-- the claim's history too (see V39), which is where every tag ever used on a sheet is read from. The journal trigger is
-- made again around the change, as in V41.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN tags VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN tags VARCHAR(4000);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- The user who last edited a claim (through its form or its row's amount entry; null when never edited). Like its
-- opener, they cannot settle or approve it. Kept in the claim's history too (see V39). The journal trigger is made
-- again around the change, as in V41.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN edited_by VARCHAR(255);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
-- The rest of the sheet kept in history too, so the whole screen can be shown as of a date (see V39 and AsOf):
-- the sheet itself, statements, periods and their fixed figures, claim logs, patrons, watches, delegations and roles.
-- A column added to one of these tables must be added to its history too.
CREATE TABLE sheet_history AS SELECT * FROM sheet;
CREATE TABLE statement_history AS SELECT * FROM statement;
CREATE TABLE period_history AS SELECT * FROM period;
CREATE TABLE period_person_total_history AS SELECT * FROM period_person_total;
CREATE TABLE claim_log_history AS SELECT * FROM claim_log;
CREATE TABLE person_patron_history AS SELECT * FROM person_patron;
CREATE TABLE person_watch_history AS SELECT * FROM person_watch;
CREATE TABLE delegation_history AS SELECT * FROM delegation;
CREATE TABLE sheet_role_history AS SELECT * FROM sheet_role;

